#!/usr/bin/env python3
"""Small offline-compatible zizmor command implementation."""
import argparse
import json
import os
import re
import sys
from pathlib import Path

import cli_extra
import input_collection
import config_support
from audit_unpinned import detect_unpinned_uses
from audit_self_hosted import findings as self_hosted_findings
from output_formats import format_output
from artipacked import audit_artipacked
from dependabot_audits import audit_dependabot


def _finding(ident, desc, path, text, line, column, feature, annotation, severity, confidence="High", endline=None, endcol=None):
    lines = text.splitlines(True)
    start = sum(len(x) for x in lines[:line-1]) + column
    endline = endline or line
    endcol = len(lines[endline-1].rstrip('\r\n')) if endcol is None and endline <= len(lines) else (endcol or column+len(feature))
    end = sum(len(x) for x in lines[:endline-1]) + endcol
    route = []
    return {"ident":ident,"desc":desc,"url":"https://docs.zizmor.sh/audits/#"+ident,
      "determinations":{"confidence":confidence,"severity":severity,"persona":"Regular"},
      "locations":[{"symbolic":{"key":{"Local":{"prefix":None,"given_path":path}},"annotation":annotation,"route":{"route":route},"feature_kind":"Normal","kind":"Primary"},
      "concrete":{"location":{"start_point":{"row":line-1,"column":column},"end_point":{"row":endline-1,"column":endcol},"offset_span":{"start":start,"end":end}},"feature":feature,"comments":[]}}],"ignored":False}


def audit(record, persona):
    text=record.text; findings=[]
    if record.kind == 'dependabot':
      return audit_dependabot({'path':record.path,'text':text},persona=persona.title())
    if record.kind != 'workflows': return findings
    findings += audit_artipacked(record)
    lines=text.splitlines()
    for n,val in detect_unpinned_uses(text):
        line=lines[n-1]; col=line.find(val)
        findings.append(_finding('unpinned-uses','unpinned action reference',record.path,text,n,col,val,
          'action is not pinned to a hash (required by blanket policy)','High'))
    findings += self_hosted_findings(text, record.path, persona)
    return findings


def plain(findings):
    for f in findings:
      if f.get('ignored'): continue
      loc=next((x for x in f.get('locations',[]) if x.get('symbolic',{}).get('kind')=='Primary'),f.get('locations',[{}])[0])
      sym=loc.get('symbolic',{}); con=loc.get('concrete',{}); pos=con.get('location',{}); start=pos.get('start_point',{})
      path=(sym.get('key',{}).get('Local') or {}).get('given_path','')
      sev=f.get('determinations',{}).get('severity','Medium').lower(); prefix='error' if sev=='high' else 'warning' if sev=='medium' else 'warning'
      print(f"{prefix}[{f.get('ident')}]: {f.get('desc')}")
      print(f" --> {path}:{int(start.get('row',0))+1}:{int(start.get('column',0))+1}")
      print('  |')
      feature=con.get('feature','').rstrip('\n')
      print(f"{int(start.get('row',0))+1} | {feature}")
      print(f"  | {' '*int(start.get('column',0))}^{max(1,len(feature))} {sym.get('annotation','')}")
      print(f"  = note: audit confidence → {f.get('determinations',{}).get('confidence','Medium')}")
      print(f"  = help: audit documentation → {f.get('url','')}")
      print()


def main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    handled,out,err,status=cli_extra.handle(argv)
    if handled:
      sys.stdout.write(out);sys.stderr.write(err);return status
    if '-h' in argv or '--help' in argv:
      print(Path(__file__).with_name('docs').joinpath('snippets/help.txt').read_text(),end='');return 0
    p=argparse.ArgumentParser(add_help=False)
    p.add_argument('inputs',nargs='*');p.add_argument('--format',default='plain');p.add_argument('--collect',default='default');p.add_argument('--strict-collection',action='store_true')
    p.add_argument('--persona',default='pedantic' if '-p' in argv or '--pedantic' in argv else 'regular');p.add_argument('-p','--pedantic',action='store_true')
    p.add_argument('--min-severity',default='informational');p.add_argument('--min-confidence',default='low');p.add_argument('--no-exit-codes',action='store_true');p.add_argument('--no-config',action='store_true')
    p.add_argument('--offline','-o',action='store_true');p.add_argument('--no-online-audits',action='store_true');p.add_argument('--no-ignores',action='store_true')
    p.add_argument('--fix',nargs='?',const='safe');p.add_argument('--color',default='auto');p.add_argument('--no-progress',action='store_true');p.add_argument('-v',action='count',default=0);p.add_argument('-q',action='count',default=0)
    # Ignore unimplemented options that do not affect offline behavior.
    p.add_argument('--config');p.add_argument('--cache-dir');p.add_argument('--gh-token');p.add_argument('--gh-hostname',default='github.com');p.add_argument('--render-links',default='auto');p.add_argument('--show-audit-urls',default='auto')
    try: a, unknown=p.parse_known_args(argv)
    except SystemExit as e:return int(e.code)
    if unknown:
      print('error: unexpected argument: '+unknown[0],file=sys.stderr);return 2
    if a.format not in ('plain','json','json-v1','sarif','github'):
      print('error: invalid value for --format',file=sys.stderr);return 2
    if a.persona not in ('regular','auditor','pedantic'):
      print('error: invalid value for --persona',file=sys.stderr);return 2
    kinds=a.collect.replace(' ','').split(',')
    stdin=sys.stdin.read() if '-' in a.inputs else None
    records,invalid=input_collection.collect(a.inputs,kinds,stdin)
    if invalid:
      for item in invalid: print('invalid input: '+item,file=sys.stderr)
      return 1
    global_config = None
    if not a.no_config:
      cfgpath = a.config or os.environ.get('ZIZMOR_CONFIG')
      if cfgpath:
        if not os.path.isfile(cfgpath):
          print('invalid config: '+cfgpath,file=sys.stderr);return 1
        try: global_config=config_support.parse_config(Path(cfgpath).read_text())
        except OSError:
          print('invalid config: '+cfgpath,file=sys.stderr);return 1
    findings=[]
    for rec in records:
      current=audit(rec,'pedantic' if a.pedantic else a.persona)
      cfg=global_config
      if cfg is None and not a.no_config:
        cfgpath=config_support.discover_config(rec.path)
        if cfgpath:
          try: cfg=config_support.parse_config(Path(cfgpath).read_text())
          except OSError: cfg=None
      findings += config_support.apply_config(current,cfg,rec.path,rec.text,a.no_ignores)
    order={'informational':0,'low':1,'medium':2,'high':3}; conf={'low':0,'medium':1,'high':2}
    findings=[f for f in findings if order.get(f['determinations']['severity'].lower(),0)>=order.get(a.min_severity,0) and conf.get(f['determinations']['confidence'].lower(),0)>=conf.get(a.min_confidence,0)]
    if a.format in ('json','json-v1'): print(json.dumps(findings,indent=2,ensure_ascii=False))
    elif a.format == 'plain': plain(findings)
    elif a.format in ('sarif','github'):
      out=format_output(a.format,findings)
      print(json.dumps(out,indent=2,ensure_ascii=False) if isinstance(out,dict) else out,end='' if str(out).endswith('\n') else '\n')
    if not findings: return 0
    return 0 if a.no_exit_codes else 14

if __name__=='__main__': raise SystemExit(main())
"}

